import argparse

from fastapi import FastAPI, Header, HTTPException, Response
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import orders, plans, refunds
from app.store.db import connect, migrate
from app.store.plans import PlanError
from app.store.refunds import REJECT_REASONS, SUPPLEMENT_REASONS, RefundError

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class RefundIn(BaseModel):
    # Client-supplied dedup identity; deliberately separate from order_id/refund_id.
    refund_request_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

class RejectIn(BaseModel):
    reason_code: str = Field(default="internal_error")

class ReturnForSupplementIn(BaseModel):
    reason_code: str
    note: str = Field(min_length=1)

class SupplementIn(BaseModel):
    amount_cents: int = Field(gt=0)

class PlanItemIn(BaseModel):
    term_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

class PaymentPlanIn(BaseModel):
    items: list[PlanItemIn] = Field(min_length=1)

def _require_tenant(x_tenant: str) -> str:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    return x_tenant

def _refund_conflict(error: RefundError) -> HTTPException:
    detail: dict = {"code": error.reason_code, "message": str(error)}
    if error.refund is not None:
        detail["refund"] = error.refund
    return HTTPException(status_code=409, detail=detail)

def _plan_conflict(error: PlanError) -> HTTPException:
    detail = {"code": error.reason_code, "message": str(error)}
    return HTTPException(status_code=409, detail=detail)

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        order = orders.add_payment(tenant, order_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payment-plan", status_code=201)
def create_payment_plan(
    order_id: str, body: PaymentPlanIn, x_tenant: str = Header(default="")
) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        plan = plans.create_plan(
            tenant, order_id, [(item.term_id, item.amount_cents) for item in body.items]
        )
    except PlanError as error:
        raise _plan_conflict(error)
    if plan is None:
        raise HTTPException(status_code=404, detail="order not found")
    return plan

@app.delete("/orders/{order_id}/payment-plan")
def cancel_payment_plan(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        cancelled = plans.cancel_plan(tenant, order_id)
    except PlanError as error:
        raise _plan_conflict(error)
    if cancelled is None:
        raise HTTPException(status_code=404, detail="order not found")
    return orders.get(tenant, order_id)

@app.get("/orders/{order_id}/payment-plan")
def read_payment_plan(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    plan = plans.get_plan(tenant, order_id)
    if plan is None:
        raise HTTPException(status_code=404, detail="payment plan not found")
    return plan

@app.post("/orders/{order_id}/refunds")
def create_refund(
    order_id: str, body: RefundIn, response: Response, x_tenant: str = Header(default="")
) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        refund, created = refunds.create_refund(
            tenant, order_id, body.refund_request_id, body.amount_cents
        )
    except RefundError as error:
        raise _refund_conflict(error)
    if refund is None:
        # Missing or foreign-tenant order: same answer, no existence leak.
        raise HTTPException(status_code=404, detail="order not found")
    response.status_code = 201 if created else 200
    return refund

@app.get("/orders/{order_id}/refunds")
def list_refunds(order_id: str, x_tenant: str = Header(default="")) -> list[dict]:
    tenant = _require_tenant(x_tenant)
    rows = refunds.list_for_order(tenant, order_id)
    if rows is None:
        raise HTTPException(status_code=404, detail="order not found")
    return rows

@app.get("/refunds/{refund_id}")
def read_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    refund, _order = refunds.get_refund(tenant, refund_id=refund_id)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/complete")
def complete_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        refund = refunds.complete_refund(tenant, refund_id)
    except RefundError as error:
        raise _refund_conflict(error)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/reject")
def reject_refund(
    refund_id: str, body: RejectIn, x_tenant: str = Header(default="")
) -> dict:
    tenant = _require_tenant(x_tenant)
    if body.reason_code not in REJECT_REASONS:
        allowed = ", ".join(sorted(REJECT_REASONS))
        raise HTTPException(status_code=400, detail=f"reason_code must be one of: {allowed}")
    try:
        refund = refunds.reject_refund(tenant, refund_id, body.reason_code)
    except RefundError as error:
        raise _refund_conflict(error)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/return")
def return_refund_for_supplement(
    refund_id: str, body: ReturnForSupplementIn, response: Response,
    x_tenant: str = Header(default=""),
) -> dict:
    tenant = _require_tenant(x_tenant)
    if body.reason_code not in SUPPLEMENT_REASONS:
        allowed = ", ".join(sorted(SUPPLEMENT_REASONS))
        raise HTTPException(status_code=400, detail=f"reason_code must be one of: {allowed}")
    try:
        refund, created = refunds.return_for_supplement(
            tenant, refund_id, body.reason_code, body.note
        )
    except RefundError as error:
        raise _refund_conflict(error)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    response.status_code = 201 if created else 200
    return refund

@app.post("/refunds/{refund_id}/supplement")
def supplement_refund(
    refund_id: str, body: SupplementIn, x_tenant: str = Header(default="")
) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        refund = refunds.supplement_refund(tenant, refund_id, body.amount_cents)
    except RefundError as error:
        raise _refund_conflict(error)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.get("/refunds/{refund_id}/supplements")
def list_supplements(refund_id: str, x_tenant: str = Header(default="")) -> list[dict]:
    tenant = _require_tenant(x_tenant)
    rows = refunds.list_supplements(tenant, refund_id)
    if rows is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return rows

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

from app.store.db import connect

# Installment payment plans.
#   - A plan can only be created while the order has received no payment, and
#     the installments must sum exactly to the order amount.
#   - Cancelling a plan is likewise only allowed before any payment; it simply
#     removes the installments and never touches order money or status.
#   - With a plan in place, a payment must settle a consecutive run of
#     installments exactly (from the first unsettled one on); partial
#     installments are refused and nothing is written.

class PlanError(Exception):
    """A refusal that leaves the order and every installment untouched."""

    def __init__(self, reason_code: str, message: str):
        super().__init__(message)
        self.reason_code = reason_code

def _fetch_order(conn, tenant: str, order_id: str):
    return conn.execute(
        "SELECT amount_cents, paid_cents, currency FROM orders "
        "WHERE tenant=? AND order_id=?",
        (tenant, order_id),
    ).fetchone()

def _fetch_items(conn, tenant: str, order_id: str):
    return conn.execute(
        "SELECT term_id, seq, amount_cents, paid_cents FROM payment_plan_items "
        "WHERE tenant=? AND order_id=? ORDER BY seq",
        (tenant, order_id),
    ).fetchall()

def _has_plan(conn, tenant: str, order_id: str) -> bool:
    return conn.execute(
        "SELECT 1 FROM payment_plan_items WHERE tenant=? AND order_id=? LIMIT 1",
        (tenant, order_id),
    ).fetchone() is not None

def create_plan(tenant: str, order_id: str, items: list[tuple[str, int]]) -> dict | None:
    """Create an installment plan. items are (term_id, amount_cents) in order.

    Returns the plan view, or None when the order is invisible to this tenant.
    Raises PlanError on any rule violation; the whole plan is refused and no
    installment is written.
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        order = _fetch_order(conn, tenant, order_id)
        if order is None:
            conn.execute("ROLLBACK")
            return None
        term_ids = [term_id for term_id, _ in items]
        if not items:
            raise PlanError("invalid_plan", "plan must contain at least one installment")
        if len(set(term_ids)) != len(term_ids):
            raise PlanError("invalid_plan", "term id must be unique within the order")
        if any(amount <= 0 for _, amount in items):
            raise PlanError("invalid_plan", "installment amount must be greater than zero")
        if sum(amount for _, amount in items) != order["amount_cents"]:
            raise PlanError("invalid_plan", "installments must sum to the order amount")
        if order["paid_cents"] > 0:
            raise PlanError("order_state", "order already received payments")
        if _has_plan(conn, tenant, order_id):
            raise PlanError("plan_exists", "order already has a payment plan")
        for seq, (term_id, amount) in enumerate(items):
            conn.execute(
                "INSERT INTO payment_plan_items(tenant, order_id, term_id, seq, amount_cents) "
                "VALUES(?,?,?,?,?)",
                (tenant, order_id, term_id, seq, amount),
            )
        conn.execute("COMMIT")
    except PlanError:
        conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()
    return get_plan(tenant, order_id)

def cancel_plan(tenant: str, order_id: str) -> bool | None:
    """Cancel the plan. None: order invisible; False is never returned —
    rule violations raise PlanError. Returns True when the plan was removed."""
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        order = _fetch_order(conn, tenant, order_id)
        if order is None:
            conn.execute("ROLLBACK")
            return None
        if not _has_plan(conn, tenant, order_id):
            raise PlanError("plan_not_found", "order has no payment plan")
        if order["paid_cents"] > 0:
            raise PlanError("order_state", "order already received payments")
        conn.execute(
            "DELETE FROM payment_plan_items WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        )
        conn.execute("COMMIT")
    except PlanError:
        conn.execute("ROLLBACK")
        raise
    finally:
        conn.close()
    return True

def get_plan(tenant: str, order_id: str) -> dict | None:
    """Plan view with per-installment progress. None when the order is
    invisible to this tenant or has no plan."""
    conn = connect()
    try:
        order = _fetch_order(conn, tenant, order_id)
        if order is None:
            return None
        rows = _fetch_items(conn, tenant, order_id)
    finally:
        conn.close()
    if not rows:
        return None
    items = [
        {
            "term_id": row["term_id"],
            "amount_cents": row["amount_cents"],
            "paid_cents": row["paid_cents"],
            "settled": row["paid_cents"] >= row["amount_cents"],
        }
        for row in rows
    ]
    return {
        "tenant": tenant,
        "order_id": order_id,
        "currency": order["currency"],
        "planned_cents": sum(item["amount_cents"] for item in items),
        "settled_count": sum(1 for item in items if item["settled"]),
        "items": items,
    }

def apply_payment(conn, tenant: str, order_id: str, amount_cents: int) -> bool:
    """Apply a payment to the order's plan inside an open write transaction.

    Returns False when the order has no plan (caller falls back to plain
    payment). Raises ValueError when the amount does not equal the remaining
    amount of one or more consecutive installments starting at the first
    unsettled one; nothing is written in that case.
    """
    items = _fetch_items(conn, tenant, order_id)
    if not items:
        return False
    remaining = amount_cents
    for item in items:
        if remaining == 0:
            break
        due = item["amount_cents"] - item["paid_cents"]
        if due == 0:
            continue
        if remaining < due:
            raise ValueError(
                "payment must settle a whole number of consecutive installments"
            )
        remaining -= due
        conn.execute(
            "UPDATE payment_plan_items SET paid_cents=? "
            "WHERE tenant=? AND order_id=? AND term_id=?",
            (item["amount_cents"], tenant, order_id, item["term_id"]),
        )
    if remaining > 0:
        raise ValueError("payment exceeds the planned schedule")
    return True

